from AlgorithmImports import *
from datetime import datetime, date, timedelta, time
from collections import defaultdict


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                     .Strikes(-200, 200)
                                     .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.minute_buckets = {}
        self.last_completed_bar_end = None
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal_time = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.expiration_processing_date = None

        self.Schedule.On(
            self.DateRules.EveryDay("SPY"),
            self.TimeRules.At(15, 45),
            self._scheduled_time_stop
        )

    def OnData(self, slice: Slice):
        self._process_spy_minute(slice)
        self._process_expiration_processing()
        self._process_equity_from_exercise()

        if self.pending_signal_time is not None:
            signal_time = self.pending_signal_time
            self.pending_signal_time = None
            self._try_enter(slice, signal_time)

        self._process_profit_target(slice)

    def _process_spy_minute(self, slice: Slice):
        if self.spy.Symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy.Symbol]
        local_start = bar.EndTime.astimezone(self.TimeZone)
        local_date = local_start.date()
        local_time = local_start.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute_index = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        if minute_index < 0 or minute_index >= 390:
            return

        bucket_index = minute_index // 5
        bucket_start = datetime.combine(
            local_date,
            time(9, 30)
        ) + timedelta(minutes=bucket_index * 5)
        bucket_end = bucket_start + timedelta(minutes=5)

        key = bucket_start
        bucket = self.minute_buckets.setdefault(
            key,
            {"bars": {}, "end": bucket_end}
        )
        bucket["bars"][bar.EndTime] = bar

        completed_keys = [
            bucket_key for bucket_key, value in self.minute_buckets.items()
            if value["end"] <= local_start
        ]

        for bucket_key in sorted(completed_keys):
            value = self.minute_buckets.pop(bucket_key)

            expected_times = [
                bucket_key + timedelta(minutes=i)
                for i in range(5)
            ]

            actual_times = {
                t.astimezone(self.TimeZone).replace(second=0, microsecond=0)
                for t in value["bars"]
            }

            expected_times = {
                t.replace(tzinfo=self.TimeZone)
                for t in expected_times
            }

            if len(value["bars"]) != 5:
                continue

            if {
                t.replace(second=0, microsecond=0)
                for t in actual_times
            } != {
                t.replace(second=0, microsecond=0)
                for t in expected_times
            }:
                continue

            bars = sorted(value["bars"].values(), key=lambda x: x.EndTime)
            consolidated = TradeBar(
                value["end"],
                self.spy.Symbol,
                bars[0].Open,
                max(x.High for x in bars),
                min(x.Low for x in bars),
                bars[-1].Close,
                sum(x.Volume for x in bars),
                timedelta(minutes=5)
            )

            self._process_five_minute_bar(consolidated)

    def _process_five_minute_bar(self, bar: TradeBar):
        end_local = bar.EndTime.astimezone(self.TimeZone)
        end_time = end_local.time()

        if self.last_completed_bar_end is not None:
            if end_local <= self.last_completed_bar_end:
                return

        self.last_completed_bar_end = end_local

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if old_fast is None or old_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = old_fast <= old_slow and self.fast.Current.Value > self.slow.Current.Value

        if bullish_cross and time(9, 45) <= end_time <= time(14, 30):
            self.pending_signal_time = end_local

    def _try_enter(self, slice: Slice, signal_time: datetime):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.spy.Symbol not in slice.Bars:
            self.Debug("Skipped selection: current SPY price unavailable.")
            return

        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped selection: option chain unavailable.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped selection: no eligible call expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        target_price = self.Securities[self.spy.Symbol].Price * 1.01

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= target_price
        ]

        if not eligible:
            self.Debug("Skipped selection: no call strike at least 1% OTM.")
            return

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1, tag="Entry")
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _process_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            return

        quote = None
        for contract in slice.OptionChains[self.option.Symbol]:
            if contract.Symbol == self.held_symbol:
                quote = contract
                break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.exit_ticket = self.Liquidate(
                self.held_symbol,
                tag="50% profit target"
            )
            self.Debug(f"Exit submitted: profit target for {self.held_symbol}")

    def _scheduled_time_stop(self):
        if self.held_symbol is None or self.expiration_date is None:
            return

        current_date = self.Time.date()
        next_trading_day = self.spy.Exchange.Hours.GetNextTradingDay(current_date)

        if next_trading_day == self.expiration_date:
            if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                self.exit_ticket = self.Liquidate(
                    self.held_symbol,
                    tag="Expiration-eve time stop"
                )
                self.Debug(f"Exit submitted: expiration-eve time stop for {self.held_symbol}")

    def _process_expiration_processing(self):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            if self.expiration_processing_date != self.Time.date():
                self.expiration_processing_date = self.Time.date()
                if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                    self.exit_ticket = self.Liquidate(
                        self.held_symbol,
                        tag="Expiration processing liquidation"
                    )
                    self.Debug(
                        f"Unexpected expiration carry: liquidation submitted for "
                        f"{self.held_symbol}"
                    )

    def _process_equity_from_exercise(self):
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity != 0:
            self.Liquidate(self.spy.Symbol, tag="Unexpected exercise or assignment")
            self.Debug(
                f"Unexpected exercise or assignment: liquidated SPY quantity "
                f"{spy_quantity}"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    f"Entry filled: {self.held_symbol}, price {self.entry_price}"
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.FillQuantity < 0:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected exercise or assignment event received.")
        self.Liquidate(self.spy.Symbol, tag="Unexpected assignment liquidation")
