        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            -100,
            100,
            timedelta(days=0),
            timedelta(days=365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.bucket_end = None
        self.bucket_closes = []
        self.bucket_valid = True

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration = None

        self.exercise_block_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar)

        if self.held_option is not None:
            self._process_held_option(slice)

        if self.entry_ticket is None and not self._has_option_position():
            if self.fast_window.IsReady and self.slow_window.IsReady:
                self._evaluate_entry(slice)

    def _process_minute_bar(self, bar: TradeBar):
        end = bar.EndTime
        current_time = end.time()

        if current_time < time(9, 31) or current_time > time(16, 0):
            return

        session_start = datetime.combine(end.date(), time(9, 31))
        elapsed_minutes = int((end - session_start).total_seconds() // 60)
        bucket_index = elapsed_minutes // 5
        current_bucket_end = session_start + timedelta(
            minutes=(bucket_index + 1) * 5
        )

        if self.bucket_end is None:
            self.bucket_end = current_bucket_end

        if current_bucket_end != self.bucket_end:
            self._finish_bucket()
            self.bucket_end = current_bucket_end
            self.bucket_closes = []
            self.bucket_valid = True

        expected_end = session_start + timedelta(
            minutes=5 * len(self.bucket_closes) + 1
        )

        if end != expected_end:
            self.bucket_valid = False

        self.bucket_closes.append(float(bar.Close))

        if end == self.bucket_end:
            self._finish_bucket()
            self.bucket_end = None
            self.bucket_closes = []
            self.bucket_valid = True

    def _finish_bucket(self):
        if self.bucket_end is None:
            return

        if not self.bucket_valid or len(self.bucket_closes) != 5:
            return

        close = self.bucket_closes[-1]
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        fast_current = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow_current = sum(self.slow_window[i] for i in range(20)) / 20.0

        if self.fast_window.Count < 6 or self.slow_window.Count < 21:
            return

        fast_previous = sum(self.fast_window[i] for i in range(1, 6)) / 5.0
        slow_previous = sum(self.slow_window[i] for i in range(1, 21)) / 20.0

        bar_end_time = self.bucket_end.time()
        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        self.pending_signal = (
            fast_previous <= slow_previous
            and fast_current > slow_current
            and eligible_start <= bar_end_time <= eligible_end
        )

    def _evaluate_entry(self, slice: Slice):
        if not getattr(self, "pending_signal", False):
            return

        self.pending_signal = False

        if self.exercise_block_date == self.Time.date():
            return

        if self.entry_ticket is not None or self._has_option_position():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped selection: no current SPY option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

