from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = RollingWindow[float](5)
        self.slow = RollingWindow[float](20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol,
            self.consolidator
        )

        self.pending_signal = False
        self.current_slice = None
        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_today = False
        self.last_processed_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice

        if self.last_processed_date != self.Time.date():
            self.last_processed_date = self.Time.date()
            self.no_entry_today = False

        self._handle_expiration_and_time_stop()
        self._handle_unexpected_spy_position()

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._check_profit_target(slice)

        if self.pending_signal:
            self.pending_signal = False
            self._attempt_entry(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy_symbol:
            return

        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        if local_end.date() < self.StartDate.date():
            return

        if local_end.weekday() >= 5:
            return

        end_time = local_end.time()
        if end_time < time(9, 30) or end_time > time(16, 0):
            return

        previous_fast = self.fast[-1] if self.fast.IsReady else None
        previous_slow = self.slow[-1] if self.slow.IsReady else None

        self.fast.Add(sum(list(self.fast)[:4]) / min(self.fast.Count, 4)
                      if self.fast.Count else bar.Close)
        self.slow.Add(bar.Close)

        if self.fast.Count >= 5:
            fast_value = sum(self.fast[i] for i in range(5)) / 5.0
        else:
            fast_value = None

        if self.slow.Count >= 20:
            slow_value = sum(self.slow[i] for i in range(20)) / 20.0
        else:
            slow_value = None

        if previous_fast is None or previous_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        if previous_fast <= previous_slow and fast_value > slow_value:
            self.pending_signal = True

    def _attempt_entry(self, slice: Slice):
        if self.no_entry_today:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped selection: no current SPY option chain.")
            return

        current_price = self.Securities[self.spy_symbol].Price
        if current_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped selection: no call expiration at least seven days out.")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * current_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.held_option = selected.Symbol
        self.expiration_date = selected.Expiry.date()
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted call entry: " + str(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_price is None or self.held_option is None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_option),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            quantity = -self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    quantity,
                    tag="50% profit target"
                )
                self.Debug("Submitted profit-target exit: " + str(self.held_option))

    def _handle_expiration_and_time_stop(self):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            self.no_entry_today = True
            quantity = -holding.Quantity
            if quantity != 0:
                self._cancel_open_exit()
                self.MarketOrder(
                    self.held_option,
                    quantity,
                    tag="expiration protection"
                )
                self.Debug("Submitted expiration-protection exit.")
            return

        previous_day = self.expiration_date - timedelta(days=1)
        if self.Time.date() == previous_day and self.Time.time() >= time(15, 45):
            quantity = -holding.Quantity
            if quantity != 0 and (
                self.exit_ticket is None or self.exit_ticket.Status.IsClosed()
            ):
                self._cancel_open_exit()
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    quantity,
                    tag="pre-expiration time stop"
                )
                self.Debug("Submitted pre-expiration time-stop exit.")

    def _cancel_open_exit(self):
        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.exit_ticket.Cancel("Replacing with mandatory liquidation order.")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.no_entry_today = True
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.Liquidate(
                self.spy_symbol,
                tag="unexpected exercise or assignment handling"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Call entry filled at " + str(self.entry_price) +
                        ": " + str(order_event.Symbol)
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Call exit filled: " + str(order_event.Symbol))
                    self.exit_ticket = None
                    self.held_option = None
                    self.entry_price = None
                    self.expiration_date = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.no_entry_today = True
            self.Debug("Unexpected exercise or assignment event received.")

