                .CallsOnly()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.spy_option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_bars = []
        self._previous_fast = None
        self._previous_slow = None
        self._last_signal_bar_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self._blocked_date = None

    def OnData(self, slice: Slice):
        self._handle_expiration_and_assignment_safety()

        if self.held_option is not None and self._is_open_holding():
            self._evaluate_profit_target(slice)
            self._evaluate_time_stop()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        completed_bar = self._update_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        self._evaluate_entry(completed_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_end = self.Time.astimezone(self.TimeZone).replace(tzinfo=None)
        local_start = local_end - timedelta(minutes=1)

        if not (time(9, 30) <= local_start.time() < time(16, 0)):
            return None

        minutes_from_open = int(
            (local_start - datetime.combine(local_start.date(), time(9, 30))).total_seconds()
            // 60
        )
        bucket_index = minutes_from_open // 5
        bucket_start = datetime.combine(
            local_start.date(), time(9, 30)
        ) + timedelta(minutes=bucket_index * 5)

        if self._bucket_start is None:
            self._bucket_start = bucket_start
            self._bucket_bars = []

        if bucket_start != self._bucket_start:
            completed = None
            if len(self._bucket_bars) == 5:
                completed = self._consolidate(self._bucket_bars)

            self._bucket_start = bucket_start
            self._bucket_bars = []

            if completed is not None:
                self._bucket_bars.append(minute_bar)
                return completed

        self._bucket_bars.append(minute_bar)

        if len(self._bucket_bars) == 5:
            expected_end = self._bucket_start + timedelta(minutes=5)
            if local_end >= expected_end:
                completed = self._consolidate(self._bucket_bars)
                self._bucket_start = None
                self._bucket_bars = []
                return completed

        return None

    def _consolidate(self, bars):
        return TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

    def _evaluate_entry(self, bar: TradeBar, slice: Slice):
        bar_end = bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)

        self.fast.Update(bar_end, bar.Close)
        self.slow.Update(bar_end, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        if not bullish:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self._last_signal_bar_end == bar_end:
            return

        self._last_signal_bar_end = bar_end

        if self._blocked_date == self.Time.date():
            return

        if self.held_option is not None and self._is_open_holding():
            return

        if self._entry_order_open():
            return

        self._select_and_enter(slice)

    def _select_and_enter(self, slice: Slice):
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains:
            for contract in chain:
                expiry = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiry = min(x.Expiry.date() for x in candidates)
        candidates = [
            x for x in candidates if x.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda x: (x.Strike, str(x.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol}, "
            f"strike={selected.Strike}, expiry={nearest_expiry}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = self.Securities[
                    self.held_option
                ].Symbol.ID.Date.date()
                self.Debug(
                    f"Call entry filled: {self.held_option}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Call exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def _evaluate_profit_target(self, slice: Slice):
        if self.exit_ticket is not None:
            return

        contract = slice.OptionChains.get(self.held_option)
        bid = None
        ask = None

        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_option:
                    bid = item.BidPrice
                    ask = item.AskPrice
                    break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.exit_ticket = self.Liquidate(self.held_option)
            self.Debug(
                f"Profit target reached: {self.held_option}, midpoint={midpoint}"
            )

    def _evaluate_time_stop(self):
        if self.exit_ticket is not None or self.expiration_date is None:
            return

        today = self.Time.date()
        if today != self.expiration_date - timedelta(days=1):
            return

        local_time = self.Time.astimezone(self.TimeZone).time()
        if local_time >= time(15, 45):
            self.exit_ticket = self.Liquidate(self.held_option)
            self.Debug(f"Expiration time stop submitted: {self.held_option}")

    def _handle_expiration_and_assignment_safety(self):
        if self.held_option is not None and self.expiration_date is not None:
            if self.Time.date() >= self.expiration_date:
                self._blocked_date = self.Time.date()
                if self.exit_ticket is None:
                    self.exit_ticket = self.Liquidate(self.held_option)
                    self.Debug(
                        f"Unexpected expiration carryover; liquidation submitted: "
                        f"{self.held_option}"
                    )

        if self.Portfolio[self.spy].Invested:
            self._blocked_date = self.Time.date()
            self.Liquidate(self.spy)
            self.Debug(
                "Unexpected exercise or assignment created SPY holdings; "
                "SPY liquidation submitted."
            )

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self._blocked_date = self.Time.date()
        if self.Portfolio[self.spy].Invested:
            self.Liquidate(self.spy)
        self.Debug("Unexpected option exercise or assignment processed.")

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _is_open_holding(self):
        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Invested
        )
