from AlgorithmImports import *
from datetime import datetime, time, timedelta
from collections import deque


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.current_bucket = None
        self.bucket_bars = {}
        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_processed_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.expiration_processed_date != current_date:
            self.expiration_processed_date = None
            self.no_entry_today = False

        self._handle_expiration_processing()
        self._handle_equity_from_exercise()

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._evaluate_held_option(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        session_start = datetime.combine(bar_time.date(), time(9, 30))
        session_end = time(16, 0)

        if bar_time.time() < time(9, 30) or bar_time.time() >= session_end:
            return

        bucket_number = int((bar_time - session_start).total_seconds() // 300)
        bucket = session_start + timedelta(minutes=5 * bucket_number)

        if self.current_bucket is not None and bucket != self.current_bucket:
            self._finish_bucket(self.current_bucket, slice)

        if self.current_bucket != bucket:
            self.current_bucket = bucket
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

    def _finish_bucket(self, bucket_start: datetime, slice: Slice):
        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if all(t in self.bucket_bars for t in expected_times):
            close_price = self.bucket_bars[expected_times[-1]].Close
            self.fast_window.append(close_price)
            self.slow_window.append(close_price)

            if len(self.fast_window) >= 5 and len(self.slow_window) >= 20:
                fast_previous = sum(list(self.fast_window)[-6:-1]) / 5 \
                    if len(self.fast_window) >= 6 else None
                slow_previous = sum(list(self.slow_window)[-21:-1]) / 20 \
                    if len(self.slow_window) >= 21 else None
                fast_current = sum(self.fast_window) / 5
                slow_current = sum(self.slow_window) / 20

                bar_end = bucket_start + timedelta(minutes=5)
                eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

                if (
                    eligible_time
                    and fast_previous is not None
                    and slow_previous is not None
                    and fast_previous <= slow_previous
                    and fast_current > slow_current
                ):
                    self._try_enter(slice, close_price)

        self.bucket_bars = {}

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entry_today:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None_,
        ):
            return

        if self.entry_symbol is not None and (
            self.Portfolio[self.entry_symbol].Invested
            or self.Transactions.GetOpenOrders(self.entry_symbol)
        ):
            return

        chains = slice.OptionChains.get(self.option_symbol)
        if chains is None:
            self.Debug("Skipped selection: no current SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = [
            contract for contract in chains
            if contract.Expiry.date() >= minimum_expiry
            and contract.Right == OptionRight.Call
        ]

        if not contracts:
            self.Debug("Skipped selection: no eligible call contracts.")
            return

        expiry = min(contract.Expiry.date() for contract in contracts)
        target_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no call strike at least 1% OTM.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _evaluate_held_option(self, slice: Slice):
        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        contract = slice.OptionChains.get(self.option_symbol)
        quote = None

        if contract is not None:
            for item in contract:
                if item.Symbol == self.entry_symbol:
                    quote = item
                    break

        if quote is None or quote.BidPrice <= 0 or quote.AskPrice <= 0:
            return

        midpoint = (quote.BidPrice + quote.AskPrice) / 2
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _handle_expiration_processing(self):
        if self.entry_symbol is None:
            return

        security = self.Securities.get(self.entry_symbol)
        if security is None:
            return

        expiry_date = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date == expiry_date:
            self.no_entry_today = True
            self.expiration_processed_date = current_date
            if self.Portfolio[self.entry_symbol].Invested:
                self._submit_exit("expiration protection")
            return

        if (
            current_date == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
            and self.Portfolio[self.entry_symbol].Invested
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.entry_symbol):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.entry_symbol, -quantity)
        self.Debug(f"Exit submitted: {reason}")

    def _handle_equity_from_exercise(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.no_entry_today = True
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.entry_symbol} at {self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

        if "Exercise" in str(order_event.OrderType) or "Assignment" in str(order_event.Message):
            self.no_entry_today = True
            self.Debug("Unexpected exercise or assignment event received.")

