        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (OrderStatus.New, OrderStatus.Submitted):
                self.exit_ticket.Cancel("Profit target reached")
            self.exit_ticket = None

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.spy_liquidation_ticket is not None:
            return

        self.Debug(f"Unexpected exercise or assignment handling: SPY quantity {quantity}")
        self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        while candidate.weekday() >= 5 or not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            self.Liquidate(self.held_symbol, "End of backtest liquidation")

