from AlgorithmImports import *
from datetime import timedelta, time


class SpyBullishCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                    .Strikes(-200, 200)
                                    .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_order_id = None
        self.no_entry_today = False
        self.expiration_processed = set()

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy:
            return

        bar_end = bar.EndTime.astimezone(self.TimeZone).time()
        if bar_end < time(9, 30) or bar_end > time(16, 0):
            return

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if old_fast is None or old_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if bar_end < time(9, 45) or bar_end > time(14, 30):
            return

        if old_fast <= old_slow and self.fast.Current.Value > self.slow.Current.Value:
            self.pending_signal = True

    def OnData(self, slice):
        local_time = self.Time.astimezone(self.TimeZone)
        today = local_time.date()

        if today not in self.expiration_processed:
            self.no_entry_today = False

        self.HandleUnexpectedSpyPosition()

        if self.entry_order_id is not None:
            self.EvaluateHeldOption(slice, local_time)
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self.EvaluateHeldOption(slice, local_time)
            return

        if self.pending_signal:
            self.pending_signal = False
            if not self.no_entry_today and self.entry_order_id is None:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        current_price = self.Securities[self.spy].Price
        if current_price <= 0:
            self.Debug("Skipped selection: SPY price unavailable.")
            return

        eligible = []
        for chain in slice.OptionChains:
            if chain.Key != self.option_symbol:
                continue

            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < self.Time.date() + timedelta(days=7):
                    continue
                if contract.Strike < 1.01 * current_price:
                    continue
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped selection: no eligible SPY call.")
            return

        nearest_expiry = min(c.Expiry.date() for c in eligible)
        eligible = [
            c for c in eligible
            if c.Expiry.date() == nearest_expiry
        ]

        selected = min(
            eligible,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_symbol = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish crossover entry")
        self.entry_order_id = ticket.OrderId
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def EvaluateHeldOption(self, slice, local_time):
        symbol = self.entry_symbol
        if symbol is None:
            return

        holding = self.Portfolio[symbol]
        if not holding.Invested:
            return

        expiry = symbol.ID.Date.date()

        if local_time.date() >= expiry:
            if local_time.date() not in self.expiration_processed:
                self.expiration_processed.add(local_time.date())
                self.no_entry_today = True
                self.SubmitExit("expiration processing")
            return

        if (
            local_time.date() == expiry - timedelta(days=1)
            and local_time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.exit_order_id is not None:
            return

        quote = None
        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == symbol:
                    quote = contract
                    break
            if quote is not None:
                break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_order_id is not None:
            return

        quantity = -self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_order_id is not None:
            self.Transactions.CancelOrder(
                self.entry_order_id,
                "Exit requested: {}".format(reason)
            )

        ticket = self.MarketOrder(
            self.entry_symbol,
            quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted: {} ({})".format(self.entry_symbol, reason))

    def HandleUnexpectedSpyPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.Liquidate(self.spy, tag="Unexpected exercise or assignment")
            self.no_entry_today = True

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id:
            self.entry_price = order_event.FillPrice
            self.entry_order_id = None
            self.Debug(
                "Entry filled: {} at {:.4f}".format(
                    self.entry_symbol,
                    self.entry_price
                )
            )

        elif order_event.OrderId == self.exit_order_id:
            self.Debug(
                "Exit filled: {} at {:.4f}".format(
                    self.entry_symbol,
                    order_event.FillPrice
                )
            )
            self.exit_order_id = None
            self.entry_symbol = None
            self.entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected assignment event: liquidating resulting SPY position.")
        self.no_entry_today = True
        self.Liquidate(self.spy, tag="Unexpected assignment handling")
