                "Exit filled: {} at {:.4f}".format(
                    self.entry_symbol,
                    order_event.FillPrice
                )
            )
            self.exit_order_id = None
            self.entry_symbol = None
            self.entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected assignment event: liquidating resulting SPY position.")
        self.no_entry_today = True
        self.Liquidate(self.spy, tag="Unexpected assignment handling")

