    def _process_spy_minute(self, slice: Slice):
        if self.spy.Symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy.Symbol]
        local_end = Extensions.ConvertTo(
            bar.EndTime, self.TimeZone
        )

        if local_end.time() < time(9, 30) or local_end.time() > time(16, 0):
            return

        minute_end = local_end.replace(second=0, microsecond=0)

        if minute_end.minute % 5 != 0:
            return

        bucket_end = minute_end

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
            self.bucket_bars = []

        if bucket_end != self.current_bucket_end:
            self._finalize_bucket()
            self.current_bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._finalize_bucket()
            self.current_bucket_end = None
            self.bucket_bars = []

    def _finalize_bucket(self):
        if len(self.bucket_bars) != 5:
            return

        times = []
        for bar in self.bucket_bars:
            local_time = Extensions.ConvertTo(bar.EndTime, self.TimeZone)
            times.append(local_time)

        for previous, current in zip(times, times[1:]):
            if current - previous != timedelta(minutes=1):
                return

        close = float(self.bucket_bars[-1].Close)

        previous_fast = self._sma(self.fast_window)
        previous_slow = self._sma(self.slow_window)

        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = self._sma(self.fast_window)
        current_slow = self._sma(self.slow_window)

        bar_end = times[-1].time()
        eligible = time(9, 45) <= bar_end <= time(14, 30)

        if (
            eligible
            and previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._enter_from_current_slice(close)

    def _sma(self, window):
        if not window.IsReady:
            return None
        return sum(float(x) for x in window) / window.Count

