                self._liquidate_option("pre-expiration time stop")
                return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ]:
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol, -quantity, tag=reason
            )
            self.Debug(f"Exit submitted: {self.held_symbol}, reason: {reason}")

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ]
        )

    def _handle_expiration_processing(self, algorithm_date):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if algorithm_date >= self.expiration_date:
            self._liquidate_option("unexpected position at expiration")
            self.blocked_date = algorithm_date

    def _handle_unexpected_spy_position(self, algorithm_date):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Invested:
            self.Debug(
                f"Unexpected exercise or assignment handling: liquidating SPY "
                f"position of {holding.Quantity} shares."
            )
            self.MarketOrder(self.spy.Symbol, -holding.Quantity)
            self.blocked_date = algorithm_date

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.expiration_date = self.Securities[
                self.held_symbol
            ].Symbol.ID.Date.date()
            self.Debug(
                f"Entry filled: {self.held_symbol}, fill price {self.entry_price:.4f}."
            )

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"Exit filled: {order_event.Symbol}, fill price "
                f"{order_event.FillPrice:.4f}."
            )
            if not self.Portfolio[order_event.Symbol].Invested:
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None
